     1→import { Screen } from "@prototyp/skeletor";
     2→import type { NativeStackScreenProps } from "@react-navigation/native-stack";
     3→import {
     4→  Membership,
     5→  type RoomInfo,
     6→  StateEventType,
     7→} from "@unomed/react-native-matrix-sdk";
     8→import { MatrixCore } from "modules/matrix-client/services/MatrixCore";
     9→import { useRoomInitialization } from "modules/timeline/hooks";
    10→import { useEffect, useMemo, useState } from "react";
    11→import { useSafeAreaInsets } from "react-native-safe-area-context";
    12→import { Loading } from "shared/components";
    13→import { RoomHeader, RoomInvite, RoomTimeline } from "./fragments";
    14→
    15→export const Room: React.FC<NativeStackScreenProps<Routes, "room">> = ({
    16→  route,
    17→  navigation,
    18→}) => {
    19→  const { roomId } = route.params;
    20→  const client = MatrixCore.instance;
    21→  const room = useMemo(() => client?.getRoom(roomId), [client, roomId]);
    22→  const insets = useSafeAreaInsets();
    23→  const [roomInfo, setRoomInfo] = useState<RoomInfo | undefined>(undefined);
    24→  const [isInviteAccepted, setIsInviteAccepted] = useState(false);
    25→  const isRoomInvite = useMemo(() => {
    26→    return roomInfo?.membership === Membership.Invited && !isInviteAccepted;
    27→  }, [roomInfo, isInviteAccepted]);
    28→  const hasOngoingCall = roomInfo?.hasRoomCall ?? false;
    29→  const canJoinCall =
    30→    roomInfo?.powerLevels?.canOwnUserSendState(StateEventType.CallMember) ??
    31→    false;
    32→
    33→  const { isMembersLoading, roomMembers } = useRoomInitialization({ room });
    34→
    35→  useEffect(() => {
    36→    room?.roomInfo().then(setRoomInfo).catch(console.error);
    37→  }, [room]);
    38→
    39→  const handleStartCall = () => {
    40→    if (!client || !room) {
    41→      console.error("Client or room not available");
    42→      return;
    43→    }
    44→
    45→    navigation.navigate("elementCall", {
    46→      roomId,
    47→      roomName: room.displayName(),
    48→    });
    49→  };
    50→
    51→  const handleInviteAccepted = () => {
    52→    setIsInviteAccepted(true);
    53→  };
    54→
    55→  const handleInviteDeclined = () => {
    56→    navigation.goBack();
    57→  };
    58→
    59→  const handleRoomDetails = () => {
    60→    if (isRoomInvite || !room) return;
    61→    navigation.navigate("roomDetails", { room });
    62→  };
    63→
    64→  if (!room) return null;
    65→
    66→  if (!roomInfo) {
    67→    return (
    68→      <Screen hideTopSafeArea scrollable={false}>
    69→        <RoomHeader
    70→          room={room}
    71→          isMembersLoading={isMembersLoading}
    72→          roomMembers={roomMembers}
    73→          hasNoCallOption
    74→          topInset={insets.top}
    75→          onBack={() => navigation.goBack()}
    76→        />
    77→        <Loading isFullScreen={false} />
    78→      </Screen>
    79→    );
    80→  }
    81→
    82→  return (
    83→    <Screen hideTopSafeArea>
    84→      <RoomHeader
    85→        room={room}
    86→        isMembersLoading={isMembersLoading}
    87→        roomMembers={roomMembers}
    88→        hasNoCallOption={isRoomInvite}
    89→        hasOngoingCall={hasOngoingCall}
    90→        canJoinCall={canJoinCall}
    91→        topInset={insets.top}
    92→        onBack={() => navigation.goBack()}
    93→        onRoomDetails={handleRoomDetails}
    94→        onStartCall={handleStartCall}
    95→      />
    96→
    97→      {isRoomInvite ? (
    98→        <RoomInvite
    99→          roomId={roomId}
   100→          roomInfo={roomInfo}
   101→          onAccepted={handleInviteAccepted}
   102→          onDeclined={handleInviteDeclined}
   103→        />
   104→      ) : (
   105→        <RoomTimeline room={room} roomId={roomId} />
   106→      )}
   107→    </Screen>
   108→  );
   109→};
