     1→import {
     2→  type CreateRoomParameters,
     3→  JoinRule,
     4→  PowerLevel_Tags,
     5→  RoomHistoryVisibility,
     6→  RoomNotificationMode,
     7→  type RoomPowerLevelChanges,
     8→  RoomPreset,
     9→  RoomVisibility,
    10→  type UserProfile,
    11→} from "@unomed/react-native-matrix-sdk";
    12→import { MatrixCore } from "../../matrix-client/services/MatrixCore";
    13→
    14→export class RoomService {
    15→  public static getRooms = () => {
    16→    return MatrixCore.getClient().rooms();
    17→  };
    18→
    19→  public static getRoomInfo = (roomId: string) => {
    20→    if (!MatrixCore.instance)
    21→      throw new Error("Matrix client is not initialized");
    22→    const room = MatrixCore.instance.getRoom(roomId);
    23→    return room ?? null;
    24→  };
    25→
    26→  public static getExistingDirectRoom = async (
    27→    userId: string,
    28→  ): Promise<string | null> => {
    29→    const client = MatrixCore.getClient();
    30→
    31→    try {
    32→      const rooms = client.rooms();
    33→      for (const room of rooms) {
    34→        const roomInfo = await room.roomInfo();
    35→        if (roomInfo?.isDirect) {
    36→          const members = await room.members();
    37→          const memberList = members.nextChunk(100000) ?? [];
    38→          const hasUser = memberList.some((member) => member.userId === userId);
    39→          if (hasUser) return room.id();
    40→        }
    41→      }
    42→      return null;
    43→    } catch (error) {
    44→      console.error("Failed to check for existing direct room:", error);
    45→      return null;
    46→    }
    47→  };
    48→
    49→  public static getOrCreateDirectRoom = async (
    50→    userId: string,
    51→  ): Promise<string> => {
    52→    const client = MatrixCore.getClient();
    53→
    54→    try {
    55→      const existingRoomId = await RoomService.getExistingDirectRoom(userId);
    56→      if (existingRoomId) return existingRoomId;
    57→
    58→      const roomOptions: CreateRoomParameters = {
    59→        name: undefined,
    60→        topic: undefined,
    61→        preset: RoomPreset.PrivateChat,
    62→        avatar: undefined,
    63→        isEncrypted: true,
    64→        isDirect: true,
    65→        visibility: new RoomVisibility.Private(),
    66→        invite: [userId],
    67→        powerLevelContentOverride: undefined,
    68→        joinRuleOverride: undefined,
    69→        historyVisibilityOverride: undefined,
    70→        canonicalAlias: undefined,
    71→      };
    72→
    73→      const roomId = await client.createRoom(roomOptions);
    74→      await MatrixCore.refreshRoomList();
    75→      return roomId;
    76→    } catch (error) {
    77→      throw new Error(`Failed to get or create direct room: ${error}`);
    78→    }
    79→  };
    80→
    81→  public static createRoom = async (
    82→    roomName: string,
    83→    type: "private" | "public",
    84→    image: Asset | null,
    85→    roomTopic?: string,
    86→  ): Promise<string> => {
    87→    const client = MatrixCore.getClient();
    88→
    89→    try {
    90→      const roomOptions: CreateRoomParameters = {
    91→        name: roomName,
    92→        topic: roomTopic,
    93→        preset:
    94→          type === "private" ? RoomPreset.PrivateChat : RoomPreset.PublicChat,
    95→        avatar: undefined,
    96→        isEncrypted: type === "private",
    97→        isDirect: false,
    98→        visibility:
    99→          type === "private"
   100→            ? new RoomVisibility.Private()
   101→            : new RoomVisibility.Public(),
   102→        invite: [],
   103→        powerLevelContentOverride: undefined,
   104→        joinRuleOverride: undefined,
   105→        historyVisibilityOverride: undefined,
   106→        canonicalAlias: undefined,
   107→      };
   108→
   109→      const roomId = await client.createRoom(roomOptions);
   110→
   111→      if (image?.base64) {
   112→        const room = client.getRoom(roomId);
   113→        const bytes = Buffer.from(image.base64, "base64");
   114→        const mimeType = image.type ?? "image/jpeg";
   115→
   116→        if (!room) throw new Error("Room not found");
   117→        await room.uploadAvatar(mimeType, bytes.buffer, {
   118→          height: BigInt(32),
   119→          width: BigInt(32),
   120→          mimetype: mimeType,
   121→          size: BigInt(image.fileSize ?? 0),
   122→          thumbnailInfo: {
   123→            height: BigInt(32),
   124→            width: BigInt(32),
   125→            mimetype: mimeType,
   126→            size: BigInt(image.fileSize ?? 0),
   127→          },
   128→          thumbnailSource: undefined,
   129→          blurhash: "",
   130→          isAnimated: false,
   131→        });
   132→      }
   133→
   134→      await MatrixCore.refreshRoomList();
   135→      return roomId;
   136→    } catch (error) {
   137→      throw new Error(`Failed to create room: ${error}`);
   138→    }
   139→  };
   140→
   141→  public static updateRoom = async (
   142→    roomId: string,
   143→    displayName?: string,
   144→    topic?: string,
   145→    avatar?: Asset | null,
   146→  ) => {
   147→    const room = MatrixCore.getRoom(roomId);
   148→
   149→    if (displayName) await room.setName(displayName);
   150→    if (topic !== undefined) await room.setTopic(topic);
   151→
   152→    if (avatar === null) {
   153→      await room.removeAvatar();
   154→    } else if (avatar?.base64) {
   155→      const bytes = Buffer.from(avatar.base64, "base64");
   156→      const mimeType = avatar.type ?? "image/jpeg";
   157→
   158→      await room.uploadAvatar(mimeType, bytes.buffer, {
   159→        height: BigInt(32),
   160→        width: BigInt(32),
   161→        mimetype: mimeType,
   162→        size: BigInt(avatar.fileSize ?? 0),
   163→        thumbnailInfo: {
   164→          height: BigInt(32),
   165→          width: BigInt(32),
   166→          mimetype: mimeType,
   167→          size: BigInt(avatar.fileSize ?? 0),
   168→        },
   169→        thumbnailSource: undefined,
   170→        blurhash: "",
   171→        isAnimated: false,
   172→      });
   173→    }
   174→  };
   175→
   176→  public static leaveRoom = async (roomId: string) => {
   177→    const client = MatrixCore.getClient();
   178→    const room = MatrixCore.getRoom(roomId);
   179→    await room.leave();
   180→    const updatedRoom = client.getRoom(roomId);
   181→    if (!updatedRoom) throw new Error("Room not found after leave");
   182→    await updatedRoom.forget();
   183→    await MatrixCore.refreshRoomList();
   184→  };
   185→
   186→  public static joinRoomByAddress = async (address: string) => {
   187→    const client = MatrixCore.getClient();
   188→    const roomPreview = await client.getRoomPreviewFromRoomAlias(address);
   189→    const roomId = roomPreview.info().roomId;
   190→    await client.joinRoomById(roomId);
   191→    return roomId;
   192→  };
   193→
   194→  public static acceptRoomInvite = async (roomId: string) => {
   195→    const room = MatrixCore.getRoom(roomId);
   196→    await room.join();
   197→    await MatrixCore.refreshRoomList();
   198→  };
   199→
   200→  public static declineRoomInvite = async (roomId: string) => {
   201→    const room = MatrixCore.getRoom(roomId);
   202→    await room.leave();
   203→    await room.forget();
   204→    await MatrixCore.refreshRoomList();
   205→  };
   206→
   207→  public static invitePeopleToRoom = async (
   208→    roomId: string,
   209→    invitedPeople: UserProfile[],
   210→  ) => {
   211→    const room = MatrixCore.getRoom(roomId);
   212→    await Promise.all(
   213→      invitedPeople.map(({ userId }) => room.inviteUserById(userId)),
   214→    );
   215→  };
   216→
   217→  // Power levels
   218→
   219→  public static getUserPowerLevel = async (roomId: string, userId?: string) => {
   220→    if (!MatrixCore.instance) return null;
   221→    const room = MatrixCore.instance.getRoom(roomId);
   222→    if (!room) return null;
   223→
   224→    const member = await room.member(userId ?? MatrixCore.instance.userId());
   225→
   226→    return Number(
   227→      member.powerLevel.tag === PowerLevel_Tags.Value
   228→        ? member.powerLevel.inner.value
   229→        : 0,
   230→    );
   231→  };
   232→
   233→  public static getRoomPowerLevels = async (roomId: string) => {
   234→    if (!MatrixCore.instance) return null;
   235→    const room = MatrixCore.instance.getRoom(roomId);
   236→    if (!room) return null;
   237→    return room.getPowerLevels();
   238→  };
   239→
   240→  public static updateUserPowerLevels = async (
   241→    roomId: string,
   242→    updates: Array<{ userId: string; powerLevel: bigint }>,
   243→  ) => {
   244→    const room = MatrixCore.getRoom(roomId);
   245→    await room.updatePowerLevelsForUsers(updates);
   246→  };
   247→
   248→  public static applyRoomPowerLevelChanges = async (
   249→    roomId: string,
   250→    changes: RoomPowerLevelChanges,
   251→  ) => {
   252→    const room = MatrixCore.getRoom(roomId);
   253→    await room.applyPowerLevelChanges(changes);
   254→  };
   255→
   256→  public static resetRoomPowerLevels = async (roomId: string) => {
   257→    const room = MatrixCore.getRoom(roomId);
   258→    await room.resetPowerLevels();
   259→  };
   260→
   261→  // Room security
   262→
   263→  public static updateRoomJoinRule = async (
   264→    roomId: string,
   265→    isPublic: boolean,
   266→  ) => {
   267→    const room = MatrixCore.getRoom(roomId);
   268→    await room.updateJoinRules(
   269→      isPublic ? new JoinRule.Public() : new JoinRule.Invite(),
   270→    );
   271→  };
   272→
   273→  public static updateRoomHistoryVisibility = async (
   274→    roomId: string,
   275→    visibility: "joined" | "invited",
   276→  ) => {
   277→    const room = MatrixCore.getRoom(roomId);
   278→    await room.updateHistoryVisibility(
   279→      visibility === "joined"
   280→        ? new RoomHistoryVisibility.Joined()
   281→        : new RoomHistoryVisibility.Invited(),
   282→    );
   283→  };
   284→
   285→  public static enableRoomEncryption = async (roomId: string) => {
   286→    const room = MatrixCore.getRoom(roomId);
   287→    await room.enableEncryption();
   288→  };
   289→
   290→  // Moderation
   291→
   292→  public static removeUserFromRoom = async (
   293→    roomId: string,
   294→    userId: string,
   295→    reason?: string,
   296→  ) => {
   297→    const room = MatrixCore.getRoom(roomId);
   298→    await room.kickUser(userId, reason);
   299→    await MatrixCore.refreshRoomList();
   300→  };
   301→
   302→  public static banUserFromRoom = async (
   303→    roomId: string,
   304→    userId: string,
   305→    reason?: string,
   306→  ) => {
   307→    const room = MatrixCore.getRoom(roomId);
   308→    await room.banUser(userId, reason);
   309→    await MatrixCore.refreshRoomList();
   310→  };
   311→
   312→  public static unbanUserFromRoom = async (
   313→    roomId: string,
   314→    userId: string,
   315→    reason?: string,
   316→  ) => {
   317→    const room = MatrixCore.getRoom(roomId);
   318→    await room.unbanUser(userId, reason);
   319→    await MatrixCore.refreshRoomList();
   320→  };
   321→
   322→  // Notification settings
   323→
   324→  public static setRoomMuted = async (
   325→    roomId: string,
   326→    muted: boolean,
   327→  ): Promise<void> => {
   328→    const client = MatrixCore.getClient();
   329→    const notificationSettings = await client.getNotificationSettings();
   330→    if (muted) {
   331→      await notificationSettings.setRoomNotificationMode(
   332→        roomId,
   333→        RoomNotificationMode.Mute,
   334→      );
   335→
   336→      return;
   337→    }
   338→
   339→    await notificationSettings.restoreDefaultRoomNotificationMode(roomId);
   340→  };
   341→}
