     1→import { Block, Text } from "@prototyp/skeletor";
     2→import type { RoomInfo } from "@unomed/react-native-matrix-sdk";
     3→import { RoomService } from "modules/room/service/RoomService";
     4→import { type FC, useState } from "react";
     5→import { StyleSheet } from "react-native";
     6→import Toast from "react-native-toast-message";
     7→import { Button, Loading, UserImage } from "shared/components";
     8→import { Colors } from "shared/styles";
     9→
    10→interface Props {
    11→  roomId: string;
    12→  roomInfo: RoomInfo;
    13→  onAccepted: () => void;
    14→  onDeclined: () => void;
    15→}
    16→
    17→export const RoomInvite: FC<Props> = ({
    18→  roomId,
    19→  roomInfo,
    20→  onAccepted,
    21→  onDeclined,
    22→}) => {
    23→  const [isLoading, setIsLoading] = useState(false);
    24→  const roomInviter = roomInfo?.inviter;
    25→  const roomMembers = Number(roomInfo?.joinedMembersCount) + 1;
    26→  const roomCreator = roomInfo?.creators?.[0];
    27→
    28→  const acceptRoomInvite = async () => {
    29→    try {
    30→      setIsLoading(true);
    31→      await RoomService.acceptRoomInvite(roomId);
    32→      onAccepted();
    33→    } catch (error) {
    34→      console.error(error);
    35→      Toast.show({
    36→        type: "error",
    37→        text1:
    38→          "Failed to accept room invite. The user may have removed you from the room.",
    39→      });
    40→    } finally {
    41→      setIsLoading(false);
    42→    }
    43→  };
    44→
    45→  const declineRoomInvite = async () => {
    46→    try {
    47→      setIsLoading(true);
    48→      await RoomService.declineRoomInvite(roomId);
    49→      onDeclined();
    50→    } catch (error) {
    51→      console.error(error);
    52→      Toast.show({
    53→        type: "error",
    54→        text1: "Failed to decline room invite.",
    55→      });
    56→      setIsLoading(false);
    57→    }
    58→  };
    59→
    60→  return (
    61→    <Block flex={1} align="center" paddings={20}>
    62→      {isLoading ? (
    63→        <Loading />
    64→      ) : (
    65→        <Block
    66→          align="center"
    67→          gap={12}
    68→          background={Colors.message}
    69→          paddings={12}
    70→          border={{ borderRadius: 16 }}
    71→        >
    72→          <Block flexDirection="row" gap={8} align="center">
    73→            <UserImage
    74→              displayName={roomInviter?.displayName}
    75→              avatarUrl={roomInviter?.avatarUrl}
    76→              width={24}
    77→              height={24}
    78→            />
    79→            <Text color={Colors.white}>
    80→              {roomInviter?.displayName ?? roomInviter?.userId ?? "Someone"}{" "}
    81→              added you
